partial class VectorShape{
 public string TextContent="",TextFamily="Segoe UI";public FontStyle TextStyle;public float TextPoints=24,TextDpi=96;
 GraphicsPath TextGlyphs(){var path=new GraphicsPath();FontFamily family;try{family=new FontFamily(TextFamily);}catch{family=new FontFamily("Segoe UI");}using(family){var style=family.IsStyleAvailable(TextStyle)?TextStyle:FontStyle.Regular;using(var format=(StringFormat)StringFormat.GenericTypographic.Clone())path.AddString(TextContent,family,(int)style,TextPoints*TextDpi/72f,PointF.Empty,format);}return path;}
 public void SetTextBox(PointF origin){using(var path=TextGlyphs()){var b=path.GetBounds();float w=Math.Max(1,b.Width),h=Math.Max(1,b.Height);Points=new List<PointF>{origin,new PointF(origin.X+w,origin.Y),new PointF(origin.X,origin.Y+h)};}}
 GraphicsPath TextPath(){var path=TextGlyphs();if(Points.Count!=3||path.PointCount==0)return path;var b=path.GetBounds();float w=Math.Max(.01f,b.Width),h=Math.Max(.01f,b.Height);var a=Points[0];var u=new PointF((Points[1].X-a.X)/w,(Points[1].Y-a.Y)/w);var v=new PointF((Points[2].X-a.X)/h,(Points[2].Y-a.Y)/h);using(var m=new Matrix(u.X,u.Y,v.X,v.Y,a.X-u.X*b.X-v.X*b.Y,a.Y-u.Y*b.X-v.Y*b.Y))path.Transform(m);return path;}
 public void WriteText(BinaryWriter w){w.Write(TextContent);w.Write(TextFamily);w.Write((int)TextStyle);w.Write(TextPoints);w.Write(TextDpi);}
 public void ReadText(BinaryReader r){TextContent=r.ReadString();TextFamily=r.ReadString();TextStyle=(FontStyle)r.ReadInt32();TextPoints=r.ReadSingle();TextDpi=r.ReadSingle();if(TextContent.Length>10000||TextFamily.Length>200||(int)TextStyle<0||(int)TextStyle>3||float.IsNaN(TextPoints)||TextPoints<1||TextPoints>1000||float.IsNaN(TextDpi)||TextDpi<50||TextDpi>1200||Kind=="Text"&&Points.Count!=3)throw new InvalidDataException("Invalid vector text.");}
}
